from pathlib import Path

p = Path('src/routes/match.tsx')
s = p.read_text()

s = s.replace('const [approachCustomMin, setApproachCustomMin] = useState(50);', 'const [approachCustomMin, setApproachCustomMin] = useState(30);')
s = s.replace('const approachSetupValid = approachRanges.length > 0 && (!approachRanges.includes("custom") || (approachCustomMin >= 50 && approachCustomMax <= 250 && approachCustomMin < approachCustomMax));', 'const approachSetupValid = approachRanges.length > 0 && (!approachRanges.includes("custom") || (approachCustomMin >= 30 && approachCustomMax <= 250 && approachCustomMin < approachCustomMax));')
s = s.replace('function toggleApproachRange(id: ApproachRangeId) { setApproachRanges((items) => items.includes(id) ? items.filter((x) => x !== id) : [...items, id]); }', '''function toggleApproachRange(id: ApproachRangeId) {
    setApproachRanges((items) => {
      if (id === "custom") return items.includes("custom") ? [] : ["custom"];
      const base = items.includes("custom") ? [] : items;
      return base.includes(id) ? base.filter((x) => x !== id) : [...base, id];
    });
  }''')
s = s.replace('setApproachRanges([]); setApproachCustomMin(50); setApproachCustomMax(200);', 'setApproachRanges([]); setApproachCustomMin(30); setApproachCustomMax(200);')

old_setup = '''{step === "approach-setup" && isApproach ? <><section className="mt-5"><p className="text-[10px] font-bold uppercase text-slate-500">Inspel · Closest to Pin</p><h1 className="mt-1 font-display text-4xl">Välj avstånd</h1><p className="mt-2 text-sm text-slate-600">Välj ett eller flera intervall. SG4 varierar avstånden mellan valda intervall.</p></section><div className="mt-5 grid grid-cols-2 gap-3">{([[["50-100","50–100 m"],["100-150","100–150 m"],["150-200","150–200 m"],["custom","Eget intervall"]]] as const)[0].map(([id,label]) => { const active = approachRanges.includes(id); return <button key={id} onClick={() => toggleApproachRange(id)} className={`rounded-3xl border p-5 text-left ${active ? selectedGlass : glass}`}><span className="font-display text-2xl">{label}</span>{active ? <Check className="mt-2 h-5 w-5 text-blue-600" /> : null}</button>; })}</div>{approachRanges.includes("custom") ? <div className={`mt-4 rounded-3xl border p-4 ${glass}`}><p className="text-[10px] font-bold uppercase tracking-[0.14em] text-slate-500">Eget intervall · 50–250 m</p><div className="mt-3 grid grid-cols-2 gap-3"><label className="text-xs font-bold text-slate-600">Min<input type="number" min={50} max={249} value={approachCustomMin} onChange={(e) => setApproachCustomMin(Math.max(50, Math.min(249, Number(e.target.value) || 50)))} className="mt-1 w-full rounded-2xl border border-slate-300 bg-white/80 px-3 py-3 text-lg font-bold outline-none" /></label><label className="text-xs font-bold text-slate-600">Max<input type="number" min={51} max={250} value={approachCustomMax} onChange={(e) => setApproachCustomMax(Math.max(51, Math.min(250, Number(e.target.value) || 250)))} className="mt-1 w-full rounded-2xl border border-slate-300 bg-white/80 px-3 py-3 text-lg font-bold outline-none" /></label></div></div> : null}<button disabled={!approachSetupValid} onClick={() => setStep("length")} className="mt-5 flex w-full items-center justify-center gap-2 rounded-2xl bg-slate-950 py-4 font-display text-xl text-white disabled:opacity-30">Nästa <ChevronRight className="h-5 w-5" /></button></> : null}'''
new_setup = '''{step === "approach-setup" && isApproach ? <><section className="mt-5"><p className="text-[10px] font-bold uppercase text-slate-500">Inspel · Closest to Pin</p><h1 className="mt-1 font-display text-4xl">Välj avstånd</h1><p className="mt-2 text-sm text-slate-600">Välj ett eller flera fasta intervall, eller skapa ett eget.</p></section>{!approachRanges.includes("custom") ? <><div className="mt-5"><p className="text-[10px] font-bold uppercase tracking-[0.14em] text-slate-500">Fasta intervall</p><div className="mt-2 grid grid-cols-3 gap-2">{([[["50-100","50–100"],["100-150","100–150"],["150-200","150–200"]]] as const)[0].map(([id,label]) => { const active = approachRanges.includes(id); return <button key={id} onClick={() => toggleApproachRange(id)} className={`rounded-2xl border px-2 py-4 text-center ${active ? selectedGlass : glass}`}><span className="block font-display text-xl leading-none">{label}</span><span className="mt-1 block text-[9px] font-bold uppercase text-slate-500">meter</span>{active ? <Check className="mx-auto mt-2 h-4 w-4 text-blue-600" /> : null}</button>; })}</div></div><div className="my-4 flex items-center gap-3"><span className="h-px flex-1 bg-slate-300/80" /><span className="text-[9px] font-bold uppercase tracking-[0.16em] text-slate-400">eller</span><span className="h-px flex-1 bg-slate-300/80" /></div></> : null}<button onClick={() => toggleApproachRange("custom")} className={`w-full rounded-2xl border px-4 py-4 text-left ${approachRanges.includes("custom") ? selectedGlass : glass}`}><span className="flex items-center justify-between"><span><span className="block font-display text-xl">Eget intervall</span><span className="mt-1 block text-[10px] font-semibold text-slate-500">30–250 meter</span></span>{approachRanges.includes("custom") ? <Check className="h-5 w-5 text-blue-600" /> : <ChevronRight className="h-5 w-5 text-slate-400" />}</span></button>{approachRanges.includes("custom") ? <div className={`mt-3 rounded-3xl border p-5 ${glass}`}><div className="flex items-end justify-between"><div><p className="text-[10px] font-bold uppercase tracking-[0.14em] text-slate-500">Eget intervall</p><p className="mt-1 text-xs text-slate-500">Dra lägsta och högsta avståndet.</p></div><p className="font-display text-2xl text-slate-900">{approachCustomMin}–{approachCustomMax} m</p></div><div className="relative mt-7 h-8"><div className="absolute left-0 right-0 top-3 h-2 rounded-full bg-slate-200" /><div className="absolute top-3 h-2 rounded-full bg-slate-900" style={{ left: `${((approachCustomMin - 30) / 220) * 100}%`, right: `${100 - ((approachCustomMax - 30) / 220) * 100}%` }} /><input aria-label="Lägsta avstånd" type="range" min={30} max={249} step={1} value={approachCustomMin} onChange={(e) => setApproachCustomMin(Math.min(Number(e.target.value), approachCustomMax - 1))} className="pointer-events-none absolute inset-x-0 top-0 h-8 w-full appearance-none bg-transparent [&::-webkit-slider-runnable-track]:bg-transparent [&::-webkit-slider-thumb]:pointer-events-auto [&::-webkit-slider-thumb]:h-6 [&::-webkit-slider-thumb]:w-6 [&::-webkit-slider-thumb]:appearance-none [&::-webkit-slider-thumb]:rounded-full [&::-webkit-slider-thumb]:border-[3px] [&::-webkit-slider-thumb]:border-white [&::-webkit-slider-thumb]:bg-slate-950 [&::-webkit-slider-thumb]:shadow-md" /><input aria-label="Högsta avstånd" type="range" min={31} max={250} step={1} value={approachCustomMax} onChange={(e) => setApproachCustomMax(Math.max(Number(e.target.value), approachCustomMin + 1))} className="pointer-events-none absolute inset-x-0 top-0 h-8 w-full appearance-none bg-transparent [&::-webkit-slider-runnable-track]:bg-transparent [&::-webkit-slider-thumb]:pointer-events-auto [&::-webkit-slider-thumb]:h-6 [&::-webkit-slider-thumb]:w-6 [&::-webkit-slider-thumb]:appearance-none [&::-webkit-slider-thumb]:rounded-full [&::-webkit-slider-thumb]:border-[3px] [&::-webkit-slider-thumb]:border-white [&::-webkit-slider-thumb]:bg-slate-950 [&::-webkit-slider-thumb]:shadow-md" /></div><div className="mt-1 flex justify-between text-[10px] font-bold text-slate-500"><span>30 m</span><span>250 m</span></div></div> : null}<button disabled={!approachSetupValid} onClick={() => setStep("length")} className="mt-5 flex w-full items-center justify-center gap-2 rounded-2xl bg-slate-950 py-4 font-display text-xl text-white disabled:opacity-30">Nästa <ChevronRight className="h-5 w-5" /></button></> : null}'''
if old_setup not in s:
    raise SystemExit('approach setup block not found')
s = s.replace(old_setup, new_setup)

s = s.replace('''{!isPutting && !isShortGame ? <><Target className="mx-auto h-6 w-6 text-blue-600" /><p className="mt-3 text-[10px] font-bold uppercase text-blue-600">Gör detta</p></> : null}''', '''{!isPutting && !isShortGame ? <Target className="mx-auto h-6 w-6 text-blue-600" /> : null}''')

old_input = '''isApproach ? <section className="mt-5"><div className="text-center"><p className={`text-[10px] font-bold uppercase tracking-[0.16em] ${approachTurn === "blue" ? "text-blue-600" : "text-red-600"}`}>{current.challenge.title} · {(approachTurn === "blue" ? blueLabel : redLabel).toUpperCase()}S TUR</p><h2 className="mt-1 font-display text-2xl">Registrera miss</h2>{approachTurn === "red" && current.blueApproach ? <p className="mt-1 text-[10px] font-bold text-blue-700">{blueLabel}: {current.blueApproach.proximity.toFixed(1)} m från flaggan</p> : null}</div><div className={`mt-3 rounded-[26px] border p-4 ${approachTurn === "blue" ? blueGlass : redGlass}`}><p className="text-[10px] font-bold uppercase text-slate-500">Längdmiss</p><div className="mt-2 grid grid-cols-2 gap-2"><button onClick={() => setApproachLongDirection("short")} className={`rounded-2xl border py-3 text-sm font-bold ${approachLongDirection === "short" ? "border-slate-900 bg-slate-900 text-white" : "border-slate-300 bg-white/70"}`}>Kort</button><button onClick={() => setApproachLongDirection("long")} className={`rounded-2xl border py-3 text-sm font-bold ${approachLongDirection === "long" ? "border-slate-900 bg-slate-900 text-white" : "border-slate-300 bg-white/70"}`}>Lång</button></div><div className="mt-3 flex items-center justify-between gap-3"><button onClick={() => setApproachLong(Math.max(0, approachLong - 1))} className="flex h-11 w-11 items-center justify-center rounded-full border border-slate-300 bg-white/80"><Minus className="h-4 w-4" /></button><div className="text-center"><p className="font-display text-4xl">{approachLong}</p><p className="text-[9px] font-bold uppercase text-slate-500">meter</p></div><button onClick={() => setApproachLong(Math.min(100, approachLong + 1))} className="flex h-11 w-11 items-center justify-center rounded-full border border-slate-300 bg-white/80"><Plus className="h-4 w-4" /></button></div><p className="mt-4 text-[10px] font-bold uppercase text-slate-500">Sidmiss</p><div className="mt-2 grid grid-cols-2 gap-2"><button onClick={() => setApproachLateralDirection("left")} className={`rounded-2xl border py-3 text-sm font-bold ${approachLateralDirection === "left" ? "border-slate-900 bg-slate-900 text-white" : "border-slate-300 bg-white/70"}`}>Vänster</button><button onClick={() => setApproachLateralDirection("right")} className={`rounded-2xl border py-3 text-sm font-bold ${approachLateralDirection === "right" ? "border-slate-900 bg-slate-900 text-white" : "border-slate-300 bg-white/70"}`}>Höger</button></div><div className="mt-3 flex items-center justify-between gap-3"><button onClick={() => setApproachLateral(Math.max(0, approachLateral - 1))} className="flex h-11 w-11 items-center justify-center rounded-full border border-slate-300 bg-white/80"><Minus className="h-4 w-4" /></button><div className="text-center"><p className="font-display text-4xl">{approachLateral}</p><p className="text-[9px] font-bold uppercase text-slate-500">meter</p></div><button onClick={() => setApproachLateral(Math.min(100, approachLateral + 1))} className="flex h-11 w-11 items-center justify-center rounded-full border border-slate-300 bg-white/80"><Plus className="h-4 w-4" /></button></div><div className="mt-4 rounded-2xl bg-white/70 p-3 text-center"><p className="text-[9px] font-bold uppercase text-slate-500">Proximity</p><p className="font-display text-3xl">{approachProximityPreview.toFixed(1)} m</p></div></div><button disabled={isSubmitting} onClick={recordApproach} className="mt-3 flex w-full items-center justify-center gap-2 rounded-2xl bg-slate-950 py-4 font-display text-xl text-white disabled:opacity-30">{approachTurn === "blue" ? `Spara ${blueLabel}` : `Registrera ${redLabel}`} <ChevronRight className="h-5 w-5" /></button></section>'''
new_input = '''isApproach ? <section className="mt-4"><div className={`rounded-[24px] border px-4 py-3 ${approachTurn === "blue" ? "border-blue-400 bg-blue-600 text-white shadow-lg shadow-blue-200/60" : "border-red-400 bg-red-600 text-white shadow-lg shadow-red-200/60"}`}><div className="flex items-center gap-3"><PlayerAvatar player={approachTurn === "blue" ? blueTeam[0] : redTeam[0]} tone={approachTurn} /><div className="min-w-0 flex-1"><p className="text-[9px] font-bold uppercase tracking-[0.18em] opacity-80">Nu spelar</p><p className="truncate font-display text-2xl leading-none">{approachTurn === "blue" ? blueLabel : redLabel}</p></div><div className="rounded-full bg-white/20 px-3 py-1.5 text-[10px] font-extrabold uppercase tracking-[0.12em]">Din tur</div></div>{approachTurn === "red" && current.blueApproach ? <p className="mt-2 border-t border-white/20 pt-2 text-[10px] font-semibold opacity-90">{blueLabel}: {current.blueApproach.proximity.toFixed(1)} m från flaggan</p> : null}</div><div className={`mt-3 rounded-[24px] border p-3 ${approachTurn === "blue" ? blueGlass : redGlass}`}><div className="grid grid-cols-2 gap-2"><div className="rounded-2xl bg-white/55 p-2.5"><p className="text-[9px] font-bold uppercase text-slate-500">Längd</p><div className="mt-1.5 grid grid-cols-2 gap-1"><button onClick={() => setApproachLongDirection("short")} className={`rounded-xl border py-2 text-xs font-bold ${approachLongDirection === "short" ? "border-slate-900 bg-slate-900 text-white" : "border-slate-300 bg-white/80"}`}>Kort</button><button onClick={() => setApproachLongDirection("long")} className={`rounded-xl border py-2 text-xs font-bold ${approachLongDirection === "long" ? "border-slate-900 bg-slate-900 text-white" : "border-slate-300 bg-white/80"}`}>Lång</button></div><div className="mt-2 flex items-center justify-between"><button onClick={() => setApproachLong(Math.max(0, approachLong - 1))} className="flex h-9 w-9 items-center justify-center rounded-full border border-slate-300 bg-white/90"><Minus className="h-3.5 w-3.5" /></button><div className="text-center"><p className="font-display text-3xl leading-none">{approachLong}</p><p className="text-[8px] font-bold uppercase text-slate-500">m</p></div><button onClick={() => setApproachLong(Math.min(100, approachLong + 1))} className="flex h-9 w-9 items-center justify-center rounded-full border border-slate-300 bg-white/90"><Plus className="h-3.5 w-3.5" /></button></div></div><div className="rounded-2xl bg-white/55 p-2.5"><p className="text-[9px] font-bold uppercase text-slate-500">Sida</p><div className="mt-1.5 grid grid-cols-2 gap-1"><button onClick={() => setApproachLateralDirection("left")} className={`rounded-xl border py-2 text-xs font-bold ${approachLateralDirection === "left" ? "border-slate-900 bg-slate-900 text-white" : "border-slate-300 bg-white/80"}`}>Vänster</button><button onClick={() => setApproachLateralDirection("right")} className={`rounded-xl border py-2 text-xs font-bold ${approachLateralDirection === "right" ? "border-slate-900 bg-slate-900 text-white" : "border-slate-300 bg-white/80"}`}>Höger</button></div><div className="mt-2 flex items-center justify-between"><button onClick={() => setApproachLateral(Math.max(0, approachLateral - 1))} className="flex h-9 w-9 items-center justify-center rounded-full border border-slate-300 bg-white/90"><Minus className="h-3.5 w-3.5" /></button><div className="text-center"><p className="font-display text-3xl leading-none">{approachLateral}</p><p className="text-[8px] font-bold uppercase text-slate-500">m</p></div><button onClick={() => setApproachLateral(Math.min(100, approachLateral + 1))} className="flex h-9 w-9 items-center justify-center rounded-full border border-slate-300 bg-white/90"><Plus className="h-3.5 w-3.5" /></button></div></div></div><div className="mt-2 flex items-center justify-between rounded-xl bg-white/65 px-3 py-2"><span className="text-[9px] font-bold uppercase tracking-[0.12em] text-slate-500">Proximity</span><span className="font-display text-2xl">{approachProximityPreview.toFixed(1)} m</span></div></div><button disabled={isSubmitting} onClick={recordApproach} className={`mt-3 flex w-full items-center justify-center gap-2 rounded-2xl py-3.5 font-display text-xl text-white disabled:opacity-30 ${approachTurn === "blue" ? "bg-blue-600" : "bg-red-600"}`}>{approachTurn === "blue" ? `Spara ${blueLabel}` : `Registrera ${redLabel}`} <ChevronRight className="h-5 w-5" /></button></section>'''
if old_input not in s:
    raise SystemExit('approach input block not found')
s = s.replace(old_input, new_input)

p.write_text(s)
